export class CRUD{constructor(_ref){let{axiosInstance}=_ref;this.axiosInstance=axiosInstance}create(url,payload){return this.xhr(url,payload,"POST")}read(url){return this.xhr(url,null,"GET")}update(url,payload){return this.xhr(url,payload,"PUT")}delete(url){return this.xhr(url,null,"DELETE")}patch(url,payload){return this.xhr(url,payload,"PATCH")}async xhr(url,body,verb){let requestConfig=arguments.length>3&&arguments[3]!==undefined?arguments[3]:{};const response=await this.axiosInstance.request({method:verb,url,data:body??null,...requestConfig});if(requestConfig.responseType==="blob")return response;return response.data}}